/* Eldoria County's Midnight Promise: purposeful actions find their finest form. */
(()=>{'use strict';
const kinds={cook:'A wonderful midnight feast',craft:'A perfect midnight masterpiece',garden:'A garden of rare moonflowers',answers:'The answer I need',quest:'A neighborhood goal accomplished',home:'A home project brought to life',magic:'A spell at its fullest strength',friend:'A friendship warmed by kindness'};
function ensure(s){if(!s.cityPromise||typeof s.cityPromise!=='object'||Array.isArray(s.cityPromise))s.cityPromise={};const p=s.cityPromise;for(const key of ['claimed','answers','seen'])if(!p[key]||typeof p[key]!=='object'||Array.isArray(p[key]))p[key]={};if(!Array.isArray(p.items))p.items=[];if(!Number.isSafeInteger(p.serial)||p.serial<0)p.serial=0;return p}
function time(s){if(s.cityAtmosphere?.clock!=='real'||!globalThis.EldoriaAtmosphereModel)return null;return globalThis.EldoriaAtmosphereModel.conditions(s)}
function active(s,c=time(s)){return !!c&&c.hour===0}
function guide(s,puzzle,response){return active(s)?(Array.isArray(puzzle.answer)?[...puzzle.answer]:puzzle.answer):response}
function record(s,title,kind,purpose,c=time(s)){const p=ensure(s);p.serial++;const item={id:p.serial,title,kind,quality:'Perfect',night:c?.key||'',purpose:(purpose||'').slice(0,240)};p.items.unshift(item);p.items=p.items.slice(0,100);return item}
function snapshot(s){const l=s.cityLife||{};return{craft:s.crafted||0,magic:s.academy||0,cook:s.cookedMeals||0,garden:s.gardensTended||0,work:l.shifts||0,goals:l.questSteps||0,discoveries:Object.values(l.discoveries||{}).filter(Boolean).length,friendship:Object.values(l.friends||{}).reduce((a,b)=>a+b,0),play:l.games||0,home:Object.values(l.upgrades||{}).filter(Boolean).length,heritage:Object.values(s.cityHeritage?.completed||{}).filter(Boolean).length,story:s.silverStory?.step||0}}
function observe(s,c=time(s)){const p=ensure(s),now=snapshot(s);if(!p.initialized){p.seen=now;p.initialized=true;return 0}let n=0;for(const [kind,value]of Object.entries(now)){const old=p.seen[kind]||0;p.seen[kind]=value;if(value>old&&active(s,c)){n+=value-old;record(s,({craft:'Masterwork touched by midnight',magic:'Flawless moonlight magic',cook:'An extraordinary dish',garden:'A rare and beautiful harvest',work:'Work brought to its finest form',goals:'A goal finds its perfect path',discoveries:'A hidden wonder revealed',friendship:'A kindness perfectly received',play:'A joyful midnight triumph',home:'A home project made beautiful',heritage:'An old story brought perfectly to life',story:'The next truth comes into the light'})[kind],kind,'Completed during the Midnight Promise',c)}}return n}
function fulfill(s,kind,target='',purpose='',c=time(s)){if(!active(s,c))return{ok:false,reason:'The Midnight Promise awakens from 12:00 to 12:59 a.m. in your world’s timezone.'};if(!Object.hasOwn(kinds,kind))return{ok:false,reason:'Choose an in-game intention.'};if(['cook','craft','garden'].includes(kind))target='';if(kind==='answers')target=String(s.silverStory?.step||0);const p=ensure(s),key=c.key+':'+kind+':'+target;if(p.claimed[key])return{ok:false,reason:'This intention has already found its perfect form tonight. Choose another purpose or enjoy what you made.'};const L=globalThis.EldoriaLifeModel,H=globalThis.EldoriaHeritageModel,S=globalThis.EldoriaStoryModel,E=globalThis.EldoriaExperienceModel,l=L.ensure(s);s.life??={};s.life.bag??={};let title=kinds[kind],detail='';
if(kind==='cook'){s.cookedMeals=(s.cookedMeals||0)+1;s.life.bag['midnight feast']=(s.life.bag['midnight feast']||0)+1;detail='A fragrant, perfectly finished feast waits in your midnight pantry. You can eat it or share it.'}
if(kind==='craft'){s.crafted=(s.crafted||0)+1;s.life.bag['midnight masterwork']=(s.life.bag['midnight masterwork']||0)+1;detail='A flawless handmade treasure is yours. Its workmanship carries the county’s enchantment.'}
if(kind==='garden'){s.gardensTended=(s.gardensTended||0)+1;l.bag.flowers=(l.bag.flowers||0)+3;s.life.bag['starlit moonflower']=(s.life.bag['starlit moonflower']||0)+3;for(const plant of s.garden||[])plant.time=Math.min(plant.time,Date.now()-60001);detail='Your planted moonflowers are ready to harvest. Three rare starlit blooms and three flower materials are yours.'}
if(kind==='answers'){const m=S.current(s);if(!m)return{ok:false,reason:'The family’s mystery is complete. Choose a new neighborhood goal or discovery.'};const step=S.ensure(s).step,inv=E.cases[step];if(inv){const progress=E.progress(s,step);progress.found=inv.clues.map(v=>v.id);progress.solved=true;detail=inv.solution}else detail=m.answer===null?(step===7?'Listen to each of the eight siblings. Each voice is part of the answer.':'The reunion can take the form you choose. Midnight makes room for their wishes and yours.'):m.choices[m.answer];p.answers[String(step)]=true;title='An answer revealed: '+m.title;}
if(kind==='quest'){const q=L.quests.find(q=>q.id===target);if(!q||l.quests[target]?.complete)return{ok:false,reason:'Choose a neighborhood quest that still needs your help.'};L.acceptQuest(s,target);let info=L.questStage(s,target);if(info.quest.steps.some(st=>st.requires==='owlRead')){s.owlStories??=[];if(!s.owlStories.includes(0))s.owlStories.push(0)}while(!info.progress.complete){const r=L.answerQuest(s,target,L.P[info.step.puzzle].answer,{district:info.step.district,room:info.step.room});if(!r.ok)return r;info=L.questStage(s,target)}title=q.name+' · perfectly accomplished';detail='The quest is complete. Its usual reward is yours, and the people you helped remember your work.';}
if(kind==='home'){const u=L.upgrades.find(u=>u.id===target);if(!u||l.upgrades[target])return{ok:false,reason:'Choose an unfinished cottage project.'};l.upgrades[target]=true;l.xp+=25;title=u.name+' · beautifully brought to life';detail='The finished furniture appears in your cottage, ready to use. Midnight supplied its materials.'}
if(kind==='magic'){const a=H.activities.find(a=>a.spell===target);if(!a||H.ensure(s).spells[target])return{ok:false,reason:'Choose a spell you have not yet learned.'};let i=H.current(s,a.id);while(!i.complete){const r=H.answer(s,a.id,H.puzzles[i.step.puzzle].answer,{district:i.step.district,room:i.step.room});if(!r.ok)return r;i=H.current(s,a.id)}title=a.title+' · perfectly learned';detail='The spell and its keepsake are yours. Cast it from Magic & the original shop.'}
if(kind==='friend'){const person=L.people.find(person=>person.id===target);if(!person)return{ok:false,reason:'Choose a neighbor.'};l.friends[target]=(l.friends[target]||0)+4;L.stats(s).talks++;l.xp+=8;s.visitors??=[];if(['Pip','Fern','Liora'].includes(person.name)&&!s.visitors.includes(person.name))s.visitors.push(person.name);title='A warm midnight friendship with '+person.name;detail='Your kind intention is beautifully received. Your friendship grows by four, and eligible cottage visitors are welcomed.'}
p.claimed[key]=true;if(!l.collection.includes(title))l.collection.push(title);const item=record(s,title,kind,purpose,c);return{ok:true,title,detail,item}}
function meal(s,share=false){s.life??={};s.life.bag??={};if(!(s.life.bag['midnight feast']>0))return{ok:false,reason:'Create a midnight feast before serving one.'};s.life.bag['midnight feast']--;s.mealsEnjoyed=(s.mealsEnjoyed||0)+1;if(share){const L=globalThis.EldoriaLifeModel,l=L.ensure(s);l.friends.fern=(l.friends.fern||0)+2;L.stats(s).talks++}return{ok:true,title:share?'A perfect feast shared with Fern':'A wonderful midnight feast enjoyed'}}
globalThis.EldoriaPromiseModel={kinds,ensure,time,active,guide,record,snapshot,observe,fulfill,meal};
})();
